<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { watchHostTheme } from './theme.js'
const props = defineProps({ api:Object, pluginId:{type:String,default:'ForumSignin'}, show_switch:{type:Boolean,default:true} })
const emit = defineEmits(['close','switch','layout'])
const stats=ref(null), history=ref({total:0,items:[]}), error=ref(''), busy=ref(false), filter=ref(''), showAll=ref(false), expanded=ref([]), dayOverrides=ref({})
const states={success:['成功','success'],signed:['已签','signed'],failed:['失败','failure'],unconfirmed:['未确认','unknown'],disabled:['停用','off']}
const status=k=>k==='auth_failed'?['认证失败','failure']:k==='skipped'?['已跳过','off']:states[k]||states.unconfirmed
const sites=computed(()=>[...(stats.value?.sites||[])].sort((a,b)=>Number(['failed','unconfirmed','auth_failed'].includes(b.status))-Number(['failed','unconfirmed','auth_failed'].includes(a.status))))
const filtered=computed(()=>sites.value.filter(s=>!filter.value||status(s.status)[1]===status(filter.value)[1]))
const visible=computed(()=>showAll.value?filtered.value:filtered.value.slice(0,8))
function toggleFilter(k){filter.value=filter.value===k?'':k;showAll.value=false}
function formatTime(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return v;return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}:${String(d.getSeconds()).padStart(2,'0')}`}
function day(v){return v?formatTime(v).slice(0,10).replaceAll('/','-'):'日期未知'}
const days=computed(()=>{const m=new Map();history.value.items.forEach((item,index)=>{const d=day(item.time);if(!m.has(d))m.set(d,{day:d,records:[]});m.get(d).records.push({item,index})});return [...m.values()].sort((a,b)=>b.day.localeCompare(a.day))})
const dayOpen=d=>dayOverrides.value[d]??d===day(new Date())
const evidence={button_text:'回读按钮文本',uid:'本人 UID',date:'记录日期',record_status:'记录状态'}
function toggleDay(d){dayOverrides.value[d]=!dayOpen(d)} function toggleEvidence(i){expanded.value=expanded.value.includes(i)?expanded.value.filter(x=>x!==i):[...expanded.value,i]}
async function get(path){const r=await props.api.get(`plugin/${props.pluginId}/${path}`);if(r?.success===false)throw Error(r.message);return r?.data??r}
async function loadHistory(){const first=await get('history?page=1&size=100');const items=[...(first.items||[])];for(let p=2;items.length<first.total;p++){const n=await get(`history?page=${p}&size=100`);if(!n.items?.length)break;items.push(...n.items)}return {total:first.total,items}}
async function load(){try{[stats.value,history.value]=await Promise.all([get('stats'),loadHistory()]);expanded.value=[]}catch(e){error.value=e.message||'加载失败'}}
async function execute(action,site=''){busy.value=true;error.value='';try{const r=await props.api.post(`plugin/${props.pluginId}/${action}${site?'?site='+encodeURIComponent(site):''}`,{auth:'bear'});if(r?.success===false)throw Error(r.message);await load()}catch(e){error.value=e.message||'执行请求失败'}finally{busy.value=false}}
let stopTheme;onMounted(()=>{stopTheme=watchHostTheme();load();emit('layout',{maxWidth:'1000px'})});onBeforeUnmount(()=>stopTheme?.())
</script>
<template><div class="pt-center"><section class="card embedded-card" aria-label="论坛签到数据"><div class="card-head"><h2>论坛签到</h2><div class="row"><button v-if="show_switch" class="btn ghost" @click="emit('switch')">配置</button><button class="btn ghost" @click="emit('close')">关闭</button></div></div><div v-if="error" class="alert" role="alert">{{ error }} <button class="btn ghost mini" @click="load">重试</button></div><div v-else-if="stats" class="win"><div class="topline"><h3>今日总览</h3><div class="row"><button class="btn" :disabled="busy" @click="execute('update_info')">{{ busy?'执行中…':'更新蜂巢信息' }}</button><button class="btn ghost" :disabled="busy" @click="execute('update_info')">只读核验</button></div></div><div class="stats"><div v-for="(v,k) in {success:'今日成功',signed:'已签',failed:'失败',unconfirmed:'未确认'}" :key="k" class="stat" :class="status(k)[1]"><strong>{{ stats.today?.[k]||0 }}</strong><span>{{ v }}</span></div></div><div class="site-filters"><button v-for="(v,k) in states" :key="k" class="chip" :class="v[1]" :aria-pressed="filter===k" @click="toggleFilter(k)">{{ v[0] }}</button></div><div class="data-grid"><article v-for="site in visible" :key="site.id" class="site-card" :class="'is-'+status(site.status)[1]"><div class="site-head"><strong class="site-label"><span class="site-icon site-initial" aria-hidden="true">{{ site.name?.slice(0,1) }}</span>{{ site.name }}</strong><span class="chip" :class="status(site.status)[1]">{{ status(site.status)[0] }}</span></div><div class="row"><button class="btn ghost mini" :disabled="busy||!site.can_signin" @click="execute('signin_by_domain',site.id)">单站签到</button><button class="btn ghost mini" :disabled="busy||!site.can_verify" @click="execute('verify_site',site.id)">只读核验</button></div></article></div><button v-if="filtered.length>8" class="btn ghost sites-toggle" @click="showAll=!showAll">{{ showAll?'收起其余站点':`展开其余 ${filtered.length-8} 个站点` }}</button><div v-if="!filtered.length" class="empty">该状态暂无站点</div><section class="fengchao-info" aria-label="蜂巢个人信息"><h3>蜂巢个人信息</h3><p class="hint">同步状态：{{ stats.fengchao_sync_status || '暂无' }}</p><div class="info-grid"><span>昵称</span><strong>{{ stats.fengchao_user_info?.nickname || '—' }}</strong><span>积分</span><strong>{{ stats.fengchao_user_info?.points ?? '—' }}</strong><span>未读数</span><strong>{{ stats.fengchao_user_info?.unread_count ?? '—' }}</strong></div></section><h3>历史记录</h3></div><div class="table-wrap"><table><thead><tr><th v-for="x in ['时间','站点','状态','最近消息','证据']" :key="x">{{ x }}</th></tr></thead><tbody><template v-for="group in days" :key="group.day"><tr class="history-day"><th colspan="5"><button class="btn ghost mini" @click="toggleDay(group.day)">{{ dayOpen(group.day)?'▾':'▸' }} {{ group.day }} · {{ group.records.length }} 条记录</button></th></tr><template v-if="dayOpen(group.day)" v-for="{item,index} in group.records" :key="index"><tr><td>{{ formatTime(item.time) }}</td><td>{{ item.site }}</td><td><span class="chip" :class="status(item.status)[1]">{{ status(item.status)[0] }}</span></td><td>{{ [item.message,item.reward].filter(Boolean).join(' ') }}</td><td><button class="btn ghost mini" @click="toggleEvidence(index)">{{ expanded.includes(index)?'收起证据':'展开证据' }}</button></td></tr><tr v-if="expanded.includes(index)" class="evidence"><td colspan="5"><div class="evidence-grid"><div v-for="(label,key) in evidence" :key="key"><span>{{ label }}</span>{{ item.evidence?.[key]||'' }}</div></div></td></tr></template></template><tr v-if="!history.items.length"><td colspan="5" class="muted">暂无历史记录</td></tr></tbody></table></div><div class="footer"><div class="legend"><span v-for="(v,k) in states" :key="k" class="chip" :class="v[1]">{{ v[0] }}</span></div></div></section></div></template>
<style scoped src="./preview.css"></style>
